{
 "path": "programs/task-2e28e856.py",
 "content": "def transform(grid):
    """Extract the original patch under the 8s using its reflected counterpart."""
    h, w = len(grid), len(grid[0])
    marked = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not marked:
        return [row[:] for row in grid]

    r0 = min(r for r, _ in marked)
    r1 = max(r for r, _ in marked)
    c0 = min(c for _, c in marked)
    c1 = max(c for _, c in marked)

    # The underlying canvas is 32x32 (the visible inputs are cropped to 30x30),
    # so corresponding reflected coordinates sum to 31.
    horizontal_ok = all(0 <= 31 - c < w for c in range(c0, c1 + 1))
    if horizontal_ok:
        horizontal = [
            [grid[r][31 - c] for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)
        ]
        if all(value != 8 for row in horizontal for value in row):
            return horizontal

    vertical_ok = all(0 <= 31 - r < h for r in range(r0, r1 + 1))
    if vertical_ok:
        vertical = [
            [grid[31 - r][c] for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)
        ]
        if all(value != 8 for row in vertical for value in row):
            return vertical

    # If neither complete counterpart is visible, return the visible part of
    # the horizontal counterpart, padding unavailable columns with 0.
    return [
        [grid[r][31 - c] if 0 <= 31 - c < w else 0
         for c in range(c0, c1 + 1)]
        for r in range(r0, r1 + 1)
    ]
"
